import { z } from "zod";
import { limits } from "./limits.ts";
import { keyModeSchema } from "./enums.ts";

export const uuidSchema = z.uuid();
export const isoDateTimeSchema = z.iso.datetime({ offset: true });

/** Short id used in URLs: /loop/dark-keys-k3j9x0a2bq. Generated by the database. */
export const publicIdSchema = z.string().regex(/^[0-9a-z]{10}$/);

export const handleSchema = z
  .string()
  .regex(new RegExp(limits.text.handlePattern), "Handles are 3 to 24 characters: a to z, 0 to 9 and underscore.");

export const slugSchema = z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/).max(80);

export const tagNameSchema = z
  .string()
  .trim()
  .toLowerCase()
  .min(limits.tags.minLength)
  .max(limits.tags.maxLength);

export const titleSchema = z.string().trim().min(1).max(limits.text.titleMax);
export const descriptionSchema = z.string().trim().max(limits.text.descriptionMax);
export const bpmSchema = z.number().min(limits.bpm.min).max(limits.bpm.max);
export const splitPercentSchema = z
  .int()
  .min(limits.licenses.split_on_placement.minPercent)
  .max(limits.licenses.split_on_placement.maxPercent);

/** Opaque list cursor. Built server-side from the sort value and the id; clients never parse it. */
export const cursorSchema = z.string().min(1).max(200);

/** MIDI note number. 60 = middle C (C4). */
export const midiPitchSchema = z.int().min(0).max(127);

// ---------------------------------------------------------------------------
// Musical key: stored as a root (0 = C) and a mode so compatible-key filters are a simple query.

export const musicalKeySchema = z.object({
  root: z.int().min(0).max(11),
  mode: keyModeSchema,
});
export type MusicalKey = z.infer<typeof musicalKeySchema>;

export { formatKey, parseKey, compatibleKeys } from "./format.ts";

// ---------------------------------------------------------------------------
// Waveform peaks: 800 unsigned bytes (0 to 255), base64 in JSON so a row needs no second request.

/** Waveform peaks: limits.waveform.peakPoints bytes, base64-encoded. */
const peaksBase64Length = Math.ceil(limits.waveform.peakPoints / 3) * 4;
export const peaksSchema = z
  .base64()
  // The length check survives into the generated JSON Schema (the refine below does not), so the
  // worker's contract gate also refuses a short peaks array (PR #8 contract review).
  .length(peaksBase64Length)
  .refine((s) => (s.length / 4) * 3 - (s.endsWith("==") ? 2 : s.endsWith("=") ? 1 : 0) === limits.waveform.peakPoints, {
    message: `peaks are ${limits.waveform.peakPoints} bytes`,
  });

export { encodePeaks, decodePeaks } from "./format.ts";

/** A path on this site: starts with one slash, never "//" or "/\" (which browsers treat as another host). */
export const sameSitePathSchema = z.string().regex(/^\/(?![/\\])/, "Must be a same-site path");
